using System;
using System.Text;
using UnityEngine;

public class FishM2Probe
{
    public static void Run()
    {
        StringBuilder sb = new StringBuilder();
        Type controller = Type.GetType("Module.Fish.FishingController, Assembly-CSharp");
        Type encounter = Type.GetType("Module.Fish.Model.IFishingEncounter, Assembly-CSharp");
        Type instance = Type.GetType("Module.Fish.Model.FishInstance, Assembly-CSharp");
        Type hookView = Type.GetType("Module.Fish.View.HookViewController, Assembly-CSharp");

        sb.AppendLine("controller implements IFishingEncounter = " +
                      (controller != null && encounter != null && Array.IndexOf(controller.GetInterfaces(), encounter) >= 0));
        sb.AppendLine("FishInstance.IsHooked = " + (instance != null && instance.GetField("IsHooked") != null));
        sb.AppendLine("FishInstance.FleeTimer = " + (instance != null && instance.GetField("FleeTimer") != null));

        string[] types = new string[]
        {
            "Module.Fish.Service.FishDetectionService, Assembly-CSharp",
            "Module.Fish.Service.FishCarryService, Assembly-CSharp",
            "Module.Fish.Model.HookState.TangledHookState, Module.Fish.Model",
            "Module.Fish.Model.TangledHookState, Assembly-CSharp",
            "Module.Fish.Model.HookLateralMover, Assembly-CSharp",
            "Module.Fish.Model.CatchRecord, Assembly-CSharp",
            "Module.Fish.Model.FishCaptureInfo, Assembly-CSharp",
            "Module.Fish.Type.PenaltyType, Assembly-CSharp"
        };

        for (int i = 0; i < types.Length; i++)
            sb.AppendLine((Type.GetType(types[i]) != null ? "OK      " : "MISSING ") + types[i].Split(',')[0]);

        if (hookView != null)
        {
            System.Reflection.MethodInfo[] methods = hookView.GetMethods();
            int overload5 = 0;

            for (int i = 0; i < methods.Length; i++)
            {
                if (methods[i].Name == "Initialize" && methods[i].GetParameters().Length == 5)
                    overload5++;
            }

            sb.AppendLine("HookViewController.Initialize(5 args) = " + (overload5 > 0));
        }

        Debug.Log("[FishM2Probe]\n" + sb);
    }
}
